import{_ as l,a0 as p,w as r,s as o,ao as c,I as i,x as n,a1 as a,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"如何在 Centos 8 / RHEL 8 上安裝和配置 VNC 服務器 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Centos 8 / RHEL 8 上安裝和配置 VNC 服務器 | LCTT (201910) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Centos 8 / RHEL 8 上安裝和配置 VNC 服務器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Centos 8 / RHEL 8 上安裝和配置 VNC 服務器 | LCTT (201910) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201910/20191006 How to Install and Configure VNC Server on Centos 8 - RHEL 8","title":"如何在 Centos 8 / RHEL 8 上安裝和配置 VNC 服務器","tag":"201910","desc":""},"relativePath":"201910/20191006 How to Install and Configure VNC Server on Centos 8 - RHEL 8.md","filePath":"[post].md"}'),d={name:"201910/20191006 How to Install and Configure VNC Server on Centos 8 - RHEL 8.md"};function h(u,s,g,C,k,v){const e=p("Link");return r(),o("div",null,[s[15]||(s[15]=c(`<h1 id="如何在-centos-8-rhel-8-上安裝和配置-vnc-服務器" tabindex="-1">如何在 Centos 8 / RHEL 8 上安裝和配置 VNC 服務器 <a class="header-anchor" href="#如何在-centos-8-rhel-8-上安裝和配置-vnc-服務器" aria-label="Permalink to “如何在 Centos 8 / RHEL 8 上安裝和配置 VNC 服務器”">​</a></h1><p>VNC（<ruby>虛擬網絡計算<rt>Virtual Network Computing</rt></ruby>）服務器是基於 GUI 的桌面共享平台，它可讓你訪問遠程桌面計算機。在 Centos 8 和 RHEL 8 系統中，默認未安裝 VNC 服務器，它需要手動安裝。在本文中，我們將通過簡單的分步指南，介紹如何在 Centos 8 / RHEL 8 上安裝 VNC 服務器。</p><h3 id="在-centos-8-rhel-8-上安裝-vnc-服務器的先決要求" tabindex="-1">在 Centos 8 / RHEL 8 上安裝 VNC 服務器的先決要求 <a class="header-anchor" href="#在-centos-8-rhel-8-上安裝-vnc-服務器的先決要求" aria-label="Permalink to “在 Centos 8 / RHEL 8 上安裝 VNC 服務器的先決要求”">​</a></h3><p>要在你的系統中安裝 VNC 服務器，請確保你的系統滿足以下要求：</p><ul><li>CentOS 8 / RHEL 8</li><li>GNOME 桌面環境</li><li>root 用户權限</li><li>DNF / YUM 軟件包倉庫</li></ul><h3 id="在-centos-8-rhel-8-上安裝-vnc-服務器的分步指導" tabindex="-1">在 Centos 8 / RHEL 8 上安裝 VNC 服務器的分步指導 <a class="header-anchor" href="#在-centos-8-rhel-8-上安裝-vnc-服務器的分步指導" aria-label="Permalink to “在 Centos 8 / RHEL 8 上安裝 VNC 服務器的分步指導”">​</a></h3><h4 id="步驟-1-安裝-gnome-桌面環境" tabindex="-1">步驟 1）安裝 GNOME 桌面環境 <a class="header-anchor" href="#步驟-1-安裝-gnome-桌面環境" aria-label="Permalink to “步驟 1）安裝 GNOME 桌面環境”">​</a></h4><p>在 CentOS 8 / RHEL 8 中安裝 VNC 服務器之前，請確保已安裝了桌面環境（DE）。如果已經安裝了 GNOME 桌面或安裝了 GUI 支持，那麼可以跳過此步驟。</p><p>在 CentOS 8 / RHEL 8 中，GNOME 是默認的桌面環境。如果你的系統中沒有它，請使用以下命令進行安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# dnf groupinstall &quot;workstation&quot;</span></span>
<span class="line"><span>或者</span></span>
<span class="line"><span>[root@linuxtechi ~]# dnf groupinstall &quot;Server with GUI</span></span></code></pre></div><p>成功安裝上面的包後，請運行以下命令啓用圖形模式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# systemctl set-default graphical</span></span></code></pre></div><p>現在重啓系統，進入 GNOME 登錄頁面（LCTT 譯註：你可以通過切換運行態來進入圖形界面）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# reboot</span></span></code></pre></div><p>重啓後，請取消註釋 <code>/etc/gdm/custom.conf</code> 中的 <code>WaylandEnable=false</code>，以使通過 vnc 進行的遠程桌面會話請求由 GNOME 桌面的 xorg 處理，來代替 Wayland 顯示管理器。</p><p>注意： Wayland 是 GNOME 中的默認顯示管理器 （GDM），並且未配置用於處理 X.org 等遠程渲染的 API。</p><h4 id="步驟-2-安裝-vnc-服務器-tigervnc-server" tabindex="-1">步驟 2）安裝 VNC 服務器（tigervnc-server） <a class="header-anchor" href="#步驟-2-安裝-vnc-服務器-tigervnc-server" aria-label="Permalink to “步驟 2）安裝 VNC 服務器（tigervnc-server）”">​</a></h4><p>接下來，我們將安裝 VNC 服務器，有很多 VNC 服務器可以選擇，出於安裝目的，我們將安裝 <code>TigerVNC 服務器</code>。它是最受歡迎的 VNC 服務器之一，並且高性能還獨立於平台，它使用户可以輕鬆地與遠程計算機進行交互。</p><p>現在，使用以下命令安裝 TigerVNC 服務器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# dnf install tigervnc-server tigervnc-server-module -y</span></span></code></pre></div><h4 id="步驟-3-為本地用户設置-vnc-密碼" tabindex="-1">步驟 3）為本地用户設置 VNC 密碼 <a class="header-anchor" href="#步驟-3-為本地用户設置-vnc-密碼" aria-label="Permalink to “步驟 3）為本地用户設置 VNC 密碼”">​</a></h4><p>假設我們希望用户 <code>pkumar</code> 使用 VNC 進行遠程桌面會話，然後切換到該用户並使用 <code>vncpasswd</code> 命令設置其密碼，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# su - pkumar</span></span>
<span class="line"><span>[root@linuxtechi ~]$ vncpasswd</span></span>
<span class="line"><span>Password:</span></span>
<span class="line"><span>Verify:</span></span>
<span class="line"><span>Would you like to enter a view-only password (y/n)? n</span></span>
<span class="line"><span>A view-only password is not used</span></span>
<span class="line"><span>[root@linuxtechi ~]$</span></span>
<span class="line"><span>[root@linuxtechi ~]$ exit</span></span>
<span class="line"><span>logout</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><h4 id="步驟-4-設置-vnc-服務器配置文件" tabindex="-1">步驟 4）設置 VNC 服務器配置文件 <a class="header-anchor" href="#步驟-4-設置-vnc-服務器配置文件" aria-label="Permalink to “步驟 4）設置 VNC 服務器配置文件”">​</a></h4><p>下一步是配置 VNC 服務器配置文件。創建含以下內容的 <code>/etc/systemd/system/vncserver@.service</code>，以便為上面的本地用户 <code>pkumar</code> 啓動 tigervnc-server 的服務。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# vim /etc/systemd/system/vncserver@.service</span></span>
<span class="line"><span>[Unit]</span></span>
<span class="line"><span>Description=Remote Desktop VNC Service</span></span>
<span class="line"><span>After=syslog.target network.target</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Service]</span></span>
<span class="line"><span>Type=forking</span></span>
<span class="line"><span>WorkingDirectory=/home/pkumar</span></span>
<span class="line"><span>User=pkumar</span></span>
<span class="line"><span>Group=pkumar</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ExecStartPre=/bin/sh -c &#39;/usr/bin/vncserver -kill %i &gt; /dev/null 2&gt;&amp;1 || :&#39;</span></span>
<span class="line"><span>ExecStart=/usr/bin/vncserver -autokill %i</span></span>
<span class="line"><span>ExecStop=/usr/bin/vncserver -kill %i</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Install]</span></span>
<span class="line"><span>WantedBy=multi-user.target</span></span></code></pre></div><p>保存並退出文件，</p><p>注意：替換上面文件中的用户名為你自己的。</p><p>默認情況下，VNC 服務器在 tcp 端口 5900+n 上監聽，其中 n 是顯示端口號，如果顯示端口號為 “1”，那麼 VNC 服務器將在 TCP 端口 5901 上監聽其請求。</p><h4 id="步驟-5-啓動-vnc-服務並允許防火牆中的端口" tabindex="-1">步驟 5）啓動 VNC 服務並允許防火牆中的端口 <a class="header-anchor" href="#步驟-5-啓動-vnc-服務並允許防火牆中的端口" aria-label="Permalink to “步驟 5）啓動 VNC 服務並允許防火牆中的端口”">​</a></h4><p>我將顯示端口號設置為 1，因此請使用以下命令在顯示端口號 “1” 上啓動並啓用 vnc 服務，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# systemctl daemon-reload</span></span>
<span class="line"><span>[root@linuxtechi ~]# systemctl start vncserver@:1.service</span></span>
<span class="line"><span>[root@linuxtechi ~]# systemctl enable vncserver@:1.service</span></span>
<span class="line"><span>Created symlink /etc/systemd/system/multi-user.target.wants/vncserver@:1.service → /etc/systemd/system/vncserver@.service.</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><p>使用下面的 <code>netstat</code> 或 <code>ss</code> 命令來驗證 VNC 服務器是否開始監聽 5901 上的請求，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# netstat -tunlp | grep 5901</span></span>
<span class="line"><span>tcp        0      0 0.0.0.0:5901            0.0.0.0:*               LISTEN      8169/Xvnc</span></span>
<span class="line"><span>tcp6       0      0 :::5901                 :::*                    LISTEN      8169/Xvnc</span></span>
<span class="line"><span>[root@linuxtechi ~]# ss -tunlp | grep -i 5901</span></span>
<span class="line"><span>tcp   LISTEN  0       5                    0.0.0.0:5901           0.0.0.0:*      users:((&quot;Xvnc&quot;,pid=8169,fd=6))                    </span></span>
<span class="line"><span>tcp   LISTEN  0       5                       [::]:5901              [::]:*      users:((&quot;Xvnc&quot;,pid=8169,fd=7))                    </span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><p>使用下面的 <code>systemctl</code> 命令驗證 VNC 服務器的狀態，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# systemctl status vncserver@:1.service</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/vncserver-status-centos8-rhel8.jpg" alt="vncserver-status-centos8-rhel8"></p><p>上面命令的輸出確認在 tcp 端口 5901 上成功啓動了 VNC。使用以下命令在系統防火牆中允許 VNC 服務器端口 “5901”，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# firewall-cmd --permanent --add-port=5901/tcp</span></span>
<span class="line"><span>success</span></span>
<span class="line"><span>[root@linuxtechi ~]# firewall-cmd --reload</span></span>
<span class="line"><span>success</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><h4 id="步驟-6-連接到遠程桌面會話" tabindex="-1">步驟 6）連接到遠程桌面會話 <a class="header-anchor" href="#步驟-6-連接到遠程桌面會話" aria-label="Permalink to “步驟 6）連接到遠程桌面會話”">​</a></h4><p>現在，我們已經準備就緒，可以查看遠程桌面連接是否正常工作。要訪問遠程桌面，請在 Windows / Linux 工作站中啓動 VNC Viewer，然後輸入 VNC 服務器的 IP 地址和端口號，然後按回車。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/VNC-Viewer-Windows10.jpg" alt="VNC-Viewer-Windows10"></p><p>接下來，它將詢問你的 VNC 密碼。輸入你先前為本地用户創建的密碼，然後單擊 “OK” 繼續。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/VNC-Viewer-Connect-CentOS8-RHEL8-VNC-Server.jpg" alt="VNC-Viewer-Connect-CentOS8-RHEL8-VNC-Server"></p><p>現在你可以看到遠程桌面，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/VNC-Desktop-Screen-CentOS8.jpg" alt="VNC-Desktop-Screen-CentOS8"></p><p>就是這樣，你已經在 Centos 8 / RHEL 8 中成功安裝了 VNC 服務器。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>希望這篇在 Centos 8 / RHEL 8 上安裝 VNC 服務器的分步指南為你提供了輕鬆設置 VNC 服務器並訪問遠程桌面的所有信息。請在下面的評論欄中提供你的意見和建議。下篇文章再見。謝謝再見！！！</p><hr>`,50)),i("p",null,[s[1]||(s[1]=n("via: ",-1)),a(e,{href:"https://www.linuxtechi.com/install-configure-vnc-server-centos8-rhel8/"},{default:t(()=>[...s[0]||(s[0]=[n("https://www.linuxtechi.com/install-configure-vnc-server-centos8-rhel8/",-1)])]),_:1})]),i("p",null,[s[6]||(s[6]=n("作者：",-1)),a(e,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:t(()=>[...s[2]||(s[2]=[n("Pradeep Kumar",-1)])]),_:1}),s[7]||(s[7]=n(" 選題：",-1)),a(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[n("lujun9972",-1)])]),_:1}),s[8]||(s[8]=n(" 譯者：",-1)),a(e,{href:"https://github.com/geekpi"},{default:t(()=>[...s[4]||(s[4]=[n("geekpi",-1)])]),_:1}),s[9]||(s[9]=n(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[n("wxy",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=n("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[n("LCTT",-1)])]),_:1}),s[13]||(s[13]=n(" 原創編譯，",-1)),a(e,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[n("Linux中國",-1)])]),_:1}),s[14]||(s[14]=n(" 榮譽推出",-1))])])}const N=l(d,[["render",h]]);export{f as __pageData,N as default};
